"use client"

import { useState } from "react"
import { format } from "date-fns"
import { Calendar as CalendarIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import {
  FormField,
  type FormFieldProps,
  type KeysOfType,
} from "@/hoogin/ui/form.field"

function parseDateValue(value: string): Date | undefined {
  const [year, month, day] = value.split("-").map(Number)
  if (!year || !month || !day) return undefined
  return new Date(year, month - 1, day)
}

export function FormDateField<
  TFormData,
  TName extends KeysOfType<TFormData, string>,
>({
  form,
  name,
  label,
  description,
  required,
  validators,
  disabled,
  dateFormat = "PPP",
  placeholder = "Select a date",
  className,
}: Omit<FormFieldProps<TFormData, TName>, "children"> & {
  disabled?: boolean
  dateFormat?: string
  placeholder?: string
}) {
  const [open, setOpen] = useState(false)

  return (
    <FormField
      form={form}
      name={name}
      label={label}
      description={description}
      required={required}
      validators={validators}
      className={className}
    >
      {(field) => {
        const invalid =
          field.state.meta.isTouched && field.state.meta.errors.length > 0
        const value = field.state.value as string
        const selected = parseDateValue(value)
        return (
          <Popover
            open={open}
            onOpenChange={(next) => {
              setOpen(next)
              if (!next) field.handleBlur()
            }}
          >
            <PopoverTrigger
              render={
                <Button
                  type="button"
                  variant="outline"
                  id={field.name}
                  disabled={disabled}
                  aria-invalid={invalid || undefined}
                  data-empty={!value}
                  className={cn(
                    "w-full justify-start text-left font-normal data-[empty=true]:text-muted-foreground",
                    className
                  )}
                />
              }
            >
              <CalendarIcon data-icon="inline-start" />
              {value
                ? selected
                  ? format(selected, dateFormat)
                  : value
                : placeholder}
            </PopoverTrigger>
            <PopoverContent className="w-auto p-0" align="start">
              <Calendar
                mode="single"
                selected={selected}
                onSelect={(date) => {
                  if (date) {
                    field.handleChange(
                      format(date, "yyyy-MM-dd") as typeof field.state.value
                    )
                  }
                  setOpen(false)
                }}
              />
            </PopoverContent>
          </Popover>
        )
      }}
    </FormField>
  )
}

"use client"

import { useState } from "react"
import { EyeIcon, EyeOffIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
import {
  FormField,
  type FormFieldProps,
  type KeysOfType,
} from "@/hoogin/ui/form.field"

export function FormPasswordField<
  TFormData,
  TName extends KeysOfType<TFormData, string>,
>({
  form,
  name,
  label,
  description,
  required,
  validators,
  disabled,
  placeholder,
  autoComplete = "current-password",
  className,
}: Omit<FormFieldProps<TFormData, TName>, "children"> & {
  disabled?: boolean
  placeholder?: string
  autoComplete?: string
}) {
  const [show, setShow] = useState(false)

  return (
    <FormField
      form={form}
      name={name}
      label={label}
      description={description}
      required={required}
      validators={validators}
      className={className}
    >
      {(field) => {
        const invalid =
          field.state.meta.isTouched && field.state.meta.errors.length > 0
        return (
          <div className="relative">
            <Input
              id={field.name}
              name={field.name}
              type={show ? "text" : "password"}
              value={field.state.value as string}
              onChange={(event) =>
                field.handleChange(
                  event.target.value as typeof field.state.value
                )
              }
              onBlur={field.handleBlur}
              disabled={disabled}
              autoComplete={autoComplete}
              aria-invalid={invalid || undefined}
              placeholder={placeholder}
              className={cn("w-full pr-8", className)}
            />
            <Button
              type="button"
              variant="ghost"
              size="icon"
              tabIndex={-1}
              aria-label={show ? "Hide password" : "Show password"}
              onClick={() => setShow((visible) => !visible)}
              className="absolute top-0 right-0 h-full w-8 rounded-l-none text-muted-foreground hover:bg-transparent hover:text-foreground"
            >
              {show ? <EyeOffIcon /> : <EyeIcon />}
            </Button>
          </div>
        )
      }}
    </FormField>
  )
}

